package com.example.domain.model.i18n

internal object DuaNe3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rahmataka_arju" to DuaText("तपाईंको कृपाको आशा गर्छु", "हे अल्लाह! म तपाईंको कृपाको आशा गर्छु, त्यसैले मलाई पलक झिम्काउने बराबर पनि मेरो आफ्नै मनको भरमा नछोड्नुहोस्, र मेरा सबै काम सुधारिदिनुहोस्। तपाईंबाहेक कोही पूज्य छैन।", "संकटग्रस्तको दुआ (दअवातुल मकरूब)।", "नबी ﷺ ले यसलाई संकटग्रस्तको दुआ भन्नुभयो।"),
        "dua_against_enemy_ahzab" to DuaText("शत्रुका सेनाविरुद्ध", "हे अल्लाह, पुस्तक उतार्नुहुने, छिटो हिसाब लिनुहुने! सेनाहरूलाई पराजित गर्नुहोस्। हे अल्लाह! उनीहरूलाई पराजित गर्नुहोस् र उनीहरूलाई हल्लाइदिनुहोस्।", "शत्रुविरुद्ध — अहजाबको युद्धको दुआ।", "शत्रुविरुद्ध नबी ﷺ को दुआ।"),
        "dua_anta_adudi" to DuaText("तपाईं नै मेरो सहारा हुनुहुन्छ", "हे अल्लाह! तपाईं नै मेरो पाखुरा र सहयोगी हुनुहुन्छ। तपाईंकै सहायताले म योजना बनाउँछु, तपाईंकै सहायताले आक्रमण गर्छु र तपाईंकै सहायताले लड्छु।", "प्रतिस्पर्धा वा ठूलो चुनौतीअघि।", "नबी ﷺ युद्धको समयमा यो भन्नुहुन्थ्यो।"),
        "dua_ikfinihim" to DuaText("उनीहरूविरुद्ध मलाई पर्याप्त हुनुहोस्", "हे अल्लाह! तपाईं जसरी चाहनुहुन्छ उनीहरूविरुद्ध मेरा लागि पर्याप्त हुनुहोस्।", "अत्याचारीहरूको खराबीबाट — असहाबुल उखदूदको केटाको दुआ।", "अल्लाहले केटालाई अत्याचारीहरूबाट बचाउनुभयो।"),
        "dua_qadarullah" to DuaText("केही नराम्रो भएमा", "यो अल्लाहको भाग्य हो, र उहाँले जे चाहनुभयो त्यही गर्नुभयो।", "कुनै अप्रिय कुरा भएमा 'काश' भन्नुको सट्टा।", "'काश' ले शैतानको ढोका खोल्छ।"),
        "dua_ala_kulli_hal" to DuaText("हरेक अवस्थामा प्रशंसा", "हरेक अवस्थामा सम्पूर्ण प्रशंसा अल्लाहका लागि हो।", "कुनै नमनपर्ने कुरा भएमा।", "नबी ﷺ नमनपर्ने कुरामा यो भन्नुहुन्थ्यो।"),
        "dua_dogs_barking" to DuaText("राति कुकुर भुकेको सुन्दा", "म धिक्कारिएको शैतानबाट अल्लाहको शरण माग्छु।", "राति कुकुर भुकेको वा गधा कराएको सुन्दा।", "तिनीहरूले त्यस्ता कुरा देख्छन् जुन तिमीहरू देख्दैनौ।"),
        "dua_leaving_home_adilla" to DuaText("पथभ्रष्टताबाट शरण", "हे अल्लाह! म तपाईंको शरण माग्छु कि म बाटो नबिराऊँ वा बिराइन नपरूँ, नचिप्लिऊँ वा चिप्लाइन नपरूँ, अन्याय नगरूँ वा ममाथि अन्याय नहोस्, मूर्खता नगरूँ वा मसँग मूर्खता नगरियोस्।", "घरबाट निस्कँदा — उम्मे सलमा (र.) को वर्णन।", "नबी ﷺ घरबाट निस्कँदा सधैँ यो पढ्नुहुन्थ्यो।"),
        "dua_ascending_descending" to DuaText("उकालो र ओरालो", "अल्लाह सबैभन्दा महान हुनुहुन्छ (उकालोमा)। — अल्लाह पवित्र हुनुहुन्छ (ओरालोमा)।", "यात्रामा उकालोमा 'अल्लाहु अकबर', ओरालोमा 'सुब्हानल्लाह'।", "यात्रामा सहाबा (र.) को अभ्यास।"),
        "dua_traveller_sahar" to DuaText("बिहानअघि यात्रीको दुआ", "सुन्नेले अल्लाहको प्रशंसा र हामीमाथि उहाँका असल कृपाहरू (अरूसम्म) सुनाइदियो। हे हाम्रा रब! हाम्रा साथी बन्नुहोस् र हामीमाथि अनुग्रह गर्नुहोस् — आगोबाट अल्लाहको शरण माग्दै (यो भन्छु)।", "यात्रामा सहरीको समयमा।", "नबी ﷺ यात्रामा सहरीको समयमा यो भन्नुहुन्थ्यो।"),
        "dua_zawwadakallah" to DuaText("यात्रीलाई: अल्लाहले तक्वाको सामल देऊन्", "अल्लाहले तिमीलाई तक्वाको सामल देऊन्, तिम्रा पाप क्षमा गरून् र तिमी जहाँ भए पनि तिम्रा लागि भलाइ सजिलो पारून्।", "यात्रीलाई बिदा गर्दा।", "नबी ﷺ ले यात्रामा जानेलाई यो दुआ दिनुभयो।"),
        "dua_traveller_to_resident" to DuaText("यात्रीको परिवारका लागि दुआ", "म तिमीहरूलाई त्यो अल्लाहको जिम्मामा सुम्पन्छु जसको जिम्मामा राखिएका अमानत खेर जाँदैनन्।", "यात्रामा जाने व्यक्तिले परिवारलाई बिदा गर्दा।", "परिवारको सुरक्षा अल्लाहको जिम्मामा।"),
        "dua_entering_village" to DuaText("गाउँ वा सहरमा प्रवेश", "हे अल्लाह, सात आकाश र तिनले छायाँ पारेका कुराहरूका रब, सात पृथ्वी र तिनले बोकेका कुराहरूका रब, शैतानहरू र तिनले बहकाएकाहरूका रब, हावाहरू र तिनले उडाएका कुराहरूका रब! हामी तपाईंसँग यस बस्ती र यसका बासिन्दाहरूको भलाइ माग्छौँ, र यसको, यसका मानिसहरूको र यसभित्र भएका कुराको खराबीबाट तपाईंको शरण माग्छौँ।", "कुनै बस्ती/सहरमा प्रवेश गर्नुअघि।", "नबी ﷺ जुन बस्तीमा प्रवेश गर्न चाहनुहुन्थ्यो त्यहाँ यो पढ्नुहुन्थ्यो।"),
        "dua_vehicle_stumbles" to DuaText("सवारी चिप्लिएमा", "अल्लाहको नाममा।", "सवारी चिप्लिएमा वा ठेस लागेमा 'शैतान नाश होस्' भन्नुको सट्टा।", "बिस्मिल्लाह भन्दा शैतान झिँगाजत्रो सानो हुन्छ।"),
        "dua_ajz_kasal_haram" to DuaText("कमजोरी र बुढ्यौलीबाट शरण", "हे अल्लाह! म तपाईंको शरण माग्छु कमजोरी र अल्छीपनबाट, कायरता र बुढ्यौलीबाट, जीवन र मृत्युको फित्नाबाट, र चिहानको सजायबाट।", "दैनिक शरणको व्यापक दुआ।", "नबी ﷺ को धेरै गरिने दुआ।"),
        "dua_sharri_ma_amiltu" to DuaText("मेरा कर्मको खराबीबाट शरण", "हे अल्लाह! म तपाईंको शरण माग्छु मैले गरेको कर्मको खराबीबाट, र मैले नगरेको कर्मको खराबीबाट।", "आइशा (र.) का अनुसार नबी ﷺ को दुआ।", "गरेको र नगरेको दुवैको परिणामबाट सुरक्षा।"),
        "dua_jahdil_bala" to DuaText("कठोर परीक्षाबाट शरण", "हे अल्लाह! म तपाईंको शरण माग्छु कठोर परीक्षाबाट, दुर्भाग्यको पकडबाट, नराम्रो निर्णयबाट र शत्रुहरूको हाँसोबाट।", "कठोर परीक्षा र शत्रुको खुसीबाट शरण।", "नबी ﷺ यी चार कुराबाट शरण माग्नुहुन्थ्यो।"),
        "dua_fitnat_ghina_faqr" to DuaText("धन र गरिबीको फित्नाबाट शरण", "हे अल्लाह! म तपाईंको शरण माग्छु अल्छीपन र बुढ्यौलीबाट, पाप र ऋणबाट, चिहानको फित्ना र सजायबाट, आगोको फित्ना र सजायबाट, धनको फित्नाको खराबीबाट, र गरिबीको फित्नाबाट।", "चिहान, जहन्नम, धन र गरिबीका फित्नाबाट शरण (दुआको भाग)।", "नबी ﷺ को व्यापक शरणको दुआ।"),
        "dua_kufr_faqr" to DuaText("कुफ्र र गरिबीबाट शरण", "हे अल्लाह! म कुफ्र र गरिबीबाट तपाईंको शरण माग्छु, र चिहानको सजायबाट तपाईंको शरण माग्छु। तपाईंबाहेक कोही पूज्य छैन।", "बिहान-साँझ तीन पटक।", "अबू बकरा (र.) ले नबी ﷺ लाई यो पढ्दै गरेको सुन्नुभयो।"),
        "dua_sharri_sami" to DuaText("मेरा इन्द्रियहरूको खराबीबाट शरण", "हे अल्लाह! म तपाईंको शरण माग्छु मेरा कानको खराबीबाट, मेरा आँखाको खराबीबाट, मेरो जिब्रोको खराबीबाट, मेरो हृदयको खराबीबाट र मेरो वासनाको खराबीबाट।", "शकल बिन हुमैद (र.) लाई सिकाइएको।", "अङ्ग र मनलाई पापबाट बचाउने दुआ।"),
        "dua_hadm_gharaq" to DuaText("अचानक मृत्यु र दुर्घटनाबाट शरण", "हे अल्लाह! म तपाईंको शरण माग्छु (घर) भत्किनबाट, उचाइबाट खस्नबाट, डुब्न, जल्न र बुढ्यौलीबाट, मृत्युको समयमा शैतानको बहकावबाट, तपाईंको मार्गबाट पिठ्युँ फर्काएर मर्नबाट, र (विषालु जनावरको) टोकाइबाट मर्नबाट।", "दुर्घटना र नराम्रो मृत्युबाट शरण।", "नबी ﷺ को शरणको दुआ।"),
        "dua_ju_khiyanah" to DuaText("भोक र विश्वासघातबाट शरण", "हे अल्लाह! म भोकबाट तपाईंको शरण माग्छु किनकि त्यो नराम्रो साथी हो, र विश्वासघातबाट तपाईंको शरण माग्छु किनकि त्यो नराम्रो भित्री साथी हो।", "भोक र विश्वासघातबाट शरण।", "नबी ﷺ को शरणको दुआ।"),
        "dua_huda_tuqa" to DuaText("मार्गदर्शन, तक्वा, पवित्रता र निरपेक्षता", "हे अल्लाह! म तपाईंसँग मार्गदर्शन, तक्वा, चारित्रिक पवित्रता र निरपेक्षता माग्छु।", "नबी ﷺ को छोटो व्यापक दुआ।", "दीन र संसारका चार आधारभूत कृपा।"),
        "dua_aslih_li_dini" to DuaText("मेरो दीन, संसार र आखिरत सुधार्नुहोस्", "हे अल्लाह! मेरो दीन सुधारिदिनुहोस् जुन मेरा हरेक कामको रक्षा हो, मेरो संसार सुधारिदिनुहोस् जसमा मेरो जीविका छ, मेरो आखिरत सुधारिदिनुहोस् जहाँ मलाई फर्किनु छ। जीवनलाई मेरा लागि हरेक भलाइमा वृद्धि बनाउनुहोस्, र मृत्युलाई हरेक खराबीबाट राहत बनाउनुहोस्।", "दीन, संसार र आखिरत — तीनवटैको सुधार।", "नबी ﷺ को व्यापक दुआ।"),
        "dua_musarrifal_qulub" to DuaText("हाम्रा हृदय तपाईंको आज्ञाकारितातर्फ फेर्नुहोस्", "हे अल्लाह, हृदय फेर्नुहुने! हाम्रा हृदयहरूलाई आफ्नो आज्ञाकारितातर्फ फेरिदिनुहोस्।", "हृदयलाई आज्ञाकारितामा स्थिर राख्ने दुआ।", "सबै मानिसका हृदय रहमानका दुई औँलाबीच छन्।"),
        "dua_jannah_nar" to DuaText("जन्नत माग्ने, आगोबाट शरण", "हे अल्लाह! म तपाईंसँग जन्नत माग्छु र आगोबाट तपाईंको शरण माग्छु।", "तशह्हुदपछि वा जुनसुकै समय।", "नबी ﷺ ले भन्नुभयो: हामी पनि यसैको वरिपरि दुआ गर्छौँ।"),
        "dua_khayri_kullih" to DuaText("सबै भलाइ, अहिले र पछि", "हे अल्लाह! म तपाईंसँग सबै भलाइ माग्छु — तुरुन्तको र ढिलोको, जुन म जान्छु र जुन जान्दिनँ — र सबै खराबीबाट तपाईंको शरण माग्छु — तुरुन्तको र ढिलोको, जुन म जान्छु र जुन जान्दिनँ। हे अल्लाह! म तपाईंसँग जन्नत र त्यसको नजिक पुर्याउने बोली र कर्म माग्छु, र आगो र त्यसको नजिक पुर्याउने बोली र कर्मबाट शरण माग्छु।", "नबी ﷺ ले आइशा (र.) लाई यो व्यापक दुआ सिकाउनुभयो (दुआको भाग)।", "हरेक भलाइ समेट्ने दुआ।"),
        "dua_ihdini_saddidni" to DuaText("मलाई मार्गदर्शन दिनुहोस् र सिधा राख्नुहोस्", "हे अल्लाह! मलाई मार्गदर्शन दिनुहोस् र मलाई सिधा राख्नुहोस्।", "नबी ﷺ ले अली (र.) लाई सिकाउनुभयो।", "मार्गदर्शनलाई बाटोको निर्देशन र सिधापनलाई तीरको सिधापनसँग सम्झ।"),
        "dua_hubbaka" to DuaText("अल्लाहको माया माग्ने", "हे अल्लाह! म तपाईंसँग तपाईंको माया माग्छु, र जसले तपाईंलाई माया गर्छ उसको माया, र यस्तो कर्म जसले मलाई तपाईंको मायासम्म पुर्याओस्। हे अल्लाह! तपाईंको मायालाई मेरो आफ्नो प्राण, मेरो परिवार र चिसो पानीभन्दा पनि प्यारो बनाइदिनुहोस्।", "दाऊद (अ.) को दुआ जुन नबी ﷺ ले बताउनुभयो।", "अल्लाहको माया सबैभन्दा ठूलो सम्पत्ति।"),
        "dua_filal_khayrat" to DuaText("असल काम गर्ने र खराबी छोड्ने", "हे अल्लाह! म तपाईंसँग असल काम गर्ने, खराब काम छोड्ने र गरिबहरूलाई माया गर्ने सामर्थ्य माग्छु, र तपाईंले मलाई क्षमा गर्नुहोस् र ममाथि दया गर्नुहोस्। र जब तपाईं कुनै समुदायलाई फित्नामा पार्न चाहनुहुन्छ, मलाई फित्नाबाट बचाएर मृत्यु दिनुहोस्। म तपाईंसँग तपाईंको माया, तपाईंलाई माया गर्नेहरूको माया र तपाईंको मायाको नजिक पुर्याउने कर्मको माया माग्छु।", "सपनामा अल्लाहले नबी ﷺ लाई यो दुआ सिकाउनुभयो।", "नबी ﷺ ले भन्नुभयो: यो सत्य हो, यसलाई सिक र सिकाऊ।"),
        "dua_bi_ilmikal_ghayb" to DuaText("जबसम्म जीवन राम्रो छ तबसम्म जीवित राख्नुहोस्", "हे अल्लाह! तपाईंको अदृश्य ज्ञान र सृष्टिमाथि तपाईंको शक्तिको आधारमा — जबसम्म तपाईंको ज्ञानमा जीवन मेरा लागि राम्रो छ, मलाई जीवित राख्नुहोस्, र जब मृत्यु राम्रो हुन्छ तब मृत्यु दिनुहोस्। हे अल्लाह! म लुकेर र खुला दुवैमा तपाईंको डर, खुसी र रिसमा सत्य बोली, र गरिबी र धनमा सन्तुलन माग्छु।", "अम्मार बिन यासिर (र.) को नमाजको दुआ (सुरुको भाग)।", "नबी ﷺ नमाजमा यो दुआ गर्नुहुन्थ्यो।"),
        "dua_ism_azam_mannan" to DuaText("इस्म-ए-आजम: अल-मन्नान", "हे अल्लाह! म तपाईंसँग यस आधारमा याचना गर्छु कि सम्पूर्ण प्रशंसा तपाईंकै लागि हो, तपाईंबाहेक कोही पूज्य छैन, तपाईं अत्यन्त उपकारी, आकाश र पृथ्वीका अद्वितीय सृष्टिकर्ता हुनुहुन्छ। हे महिमा र सम्मानका स्वामी, हे सदा जीवित, हे धारक!", "नबी ﷺ ले भन्नुभयो यो व्यक्तिले इस्म-ए-आजमसहित दुआ गर्यो।", "यो नामले दुआ गरे स्वीकार हुन्छ।"),
        "dua_ism_azam_ahad_samad" to DuaText("इस्म-ए-आजम: अल-अहद अस-समद", "हे अल्लाह! म तपाईंसँग यस आधारमा याचना गर्छु कि म साक्षी दिन्छु तपाईं नै अल्लाह हुनुहुन्छ, तपाईंबाहेक कोही पूज्य छैन, एक, निरपेक्ष, जसले कसैलाई जन्माउनुभएन र उहाँ जन्मनुभएन, र उहाँको बराबरी कोही छैन।", "नबी ﷺ ले भन्नुभयो यसले अल्लाहसँग उहाँको इस्म-ए-आजमसहित माग्यो।", "यसद्वारा मागे दिइन्छ, र दुआ गरे स्वीकार हुन्छ।"),
        "dua_thabbitni_hadiyan" to DuaText("मलाई दृढ, मार्गदर्शित र मार्गदर्शक बनाउनुहोस्", "हे अल्लाह! मलाई दृढ राख्नुहोस् र मलाई मार्गदर्शन दिने र मार्गदर्शित बनाउनुहोस्।", "नबी ﷺ ले जरीर (र.) का लागि यो दुआ गर्नुभयो (आफ्नो लागि 'सब्बितनी' भन्नुहोस्)।", "मूल दुआ जरीर (र.) का लागि 'सब्बित्हु' शब्दमा छ।"),
        "dua_rabbighfir_tub_alayya" to DuaText("मलाई क्षमा गर्नुहोस् र तौबा स्वीकार गर्नुहोस्", "हे मेरा रब! मलाई क्षमा गर्नुहोस् र मेरो तौबा स्वीकार गर्नुहोस्, निश्चय नै तपाईं तौबा स्वीकार गर्नुहुने, दयालु हुनुहुन्छ।", "एउटै सभामा सय पटक — नबी ﷺ को अभ्यास।", "सहाबाहरूले एउटै सभामा नबी ﷺ बाट यो सय पटक गनेर सुने।"),
        "dua_rafiq_ala" to DuaText("मृत्युको नजिक पुगेको व्यक्तिको दुआ", "हे अल्लाह! मलाई क्षमा गर्नुहोस्, ममाथि दया गर्नुहोस् र मलाई सर्वोच्च साथीसँग मिलाउनुहोस्।", "नबी ﷺ को अन्तिम दुआ — बिरामी आफ्नै लागि।", "नबी ﷺ ले देहावसानको समयमा यो दुआ गर्नुभयो।"),
        "dua_la_bas_tahur" to DuaText("बिरामीलाई सान्त्वना: पवित्रता", "केही हानि छैन, इन शा अल्लाह (यो रोग पापबाट) पवित्र पार्ने हो।", "बिरामी भेट्दा सान्त्वनाका लागि।", "नबी ﷺ बिरामीकहाँ जाँदा यो भन्नुहुन्थ्यो।"),
        "dua_talqeen" to DuaText("मृत्युको नजिक पुगेकाका लागि तल्कीन", "अल्लाहबाहेक कोही पूज्य छैन।", "मृत्युको नजिक पुगेको व्यक्तिको छेउमा कलिमा पढ्नुहोस् (उसलाई जबरजस्ती नगर्नुहोस्)।", "जसको अन्तिम वचन 'ला इलाहा इल्लल्लाह' हुन्छ ऊ जन्नतमा प्रवेश गर्नेछ (अबू दाऊद ३११६)।"),
        "dua_ahyini_ma_kanat" to DuaText("मृत्युको इच्छाको सट्टा", "हे अल्लाह! जबसम्म जीवन मेरा लागि राम्रो छ, मलाई जीवित राख्नुहोस्, र जब मृत्यु मेरा लागि राम्रो हुन्छ, मलाई मृत्यु दिनुहोस्।", "पीडामा मृत्युको इच्छा गर्नुको सट्टा।", "नबी ﷺ ले मृत्युको इच्छा गर्न मनाही गर्दै यो सिकाउनुभयो।"),
        "dua_for_one_i_cursed" to DuaText("जसलाई शब्दले दुःख दिएँ उसका लागि", "हे अल्लाह! जुन मोमिनलाई मैले गाली गरेको छु, त्यसलाई कयामतको दिन उसका लागि तपाईंको निकटताको माध्यम बनाइदिनुहोस्।", "रिसमा कसैलाई गाली गरेको भए उसका लागि।", "नबी ﷺ को दुआ।"),
        "dua_praising_someone" to DuaText("कसैको प्रशंसा गर्दा", "म फलानोलाई यस्तो ठान्छु, र अल्लाह नै उसको हिसाब लिनुहुने हुनुहुन्छ, र म अल्लाहको सामु कसैको पवित्रताको दाबी गर्दिनँ।", "कसैको प्रशंसा गर्नुपर्दा अतिशयोक्तिको सट्टा।", "नबी ﷺ ले प्रशंसाको यो शिष्टाचार सिकाउनुभयो।"),
        "dua_being_praised" to DuaText("जब तपाईंको प्रशंसा हुन्छ", "हे अल्लाह! उनीहरूले जे भनिरहेका छन् त्यसका लागि मलाई नसमात्नुहोस्, र मेरा ती पाप क्षमा गर्नुहोस् जुन उनीहरूलाई थाहा छैन।", "आफ्नो प्रशंसा सुनेर — एक सहाबी (र.) को अभ्यास।", "प्रशंसामा अहंकारबाट बच्ने उपाय।"),
        "dua_non_muslim_sneezes" to DuaText("गैर-मुस्लिमले हाच्छिउँ गर्दा", "अल्लाहले तिमीलाई मार्गदर्शन देऊन् र तिम्रो अवस्था सुधारून्।", "गैर-मुस्लिमले हाच्छिउँ गरेर 'अल्हम्दुलिल्लाह' भन्दा।", "यहूदीहरू नबी ﷺ को छेउमा हाच्छिउँ गर्थे कि उहाँले 'यरहमुकल्लाह' भन्नुहोस्, तब उहाँ यो भन्नुहुन्थ्यो।"),
        "dua_reply_ahl_kitab_salam" to DuaText("अहले किताबको सलामको जवाफ", "र तिमीहरूमाथि पनि।", "अहले किताबले सलाम गर्दा।", "नबी ﷺ को आदेश।"),
        "dua_fasting_invited" to DuaText("रोजामा निम्तो पाउँदा", "म रोजामा छु।", "रोजा भएको बेला निम्तो पाउँदा वा कसैले झगडा गर्दा।", "रोजेदारले निम्तो स्वीकार गरेमा आतिथेयका लागि दुआ गरोस्।"),
        "dua_for_who_gave_drink" to DuaText("जसले खुवायो-पिलायो उसका लागि", "हे अल्लाह! जसले मलाई खुवायो उसलाई खुवाउनुहोस्, र जसले मलाई पिलायो उसलाई पिलाउनुहोस्।", "जसले खुवाउँछ-पिलाउँछ उसका लागि।", "नबी ﷺ ले मिकदाद (र.) का लागि यो दुआ गर्नुभयो।"),
        "dua_eid_greeting" to DuaText("ईदको शुभकामना", "अल्लाहले हामीबाट र तिमीहरूबाट (कर्म) स्वीकार गरून्।", "ईदको दिन एकअर्कालाई — सहाबा (र.) को अभ्यास।", "सहाबाहरू ईदमा भेट्दा यो भन्थे।"),
        "dua_wedding_night" to DuaText("निकाहपछि दुलहीका लागि", "हे अल्लाह! म तपाईंसँग उनको भलाइ र जुन स्वभावमा तपाईंले उनलाई सृष्टि गर्नुभयो त्यसको भलाइ माग्छु, र उनको खराबी र त्यो स्वभावको खराबीबाट तपाईंको शरण माग्छु।", "निकाहपछि श्रीमतीको निधारमा हात राखेर।", "नबी ﷺ को शिक्षा — निकाहमा बरकत।"),
        "dua_istisqa_ibadak" to DuaText("आफ्ना दास र पशुहरूलाई पानी दिनुहोस्", "हे अल्लाह! आफ्ना दास र पशुहरूलाई पानी दिनुहोस्, आफ्नो कृपा फैलाउनुहोस् र आफ्नो मृत भूमिलाई जीवित पार्नुहोस्।", "वर्षाको माग (इस्तिस्का)।", "नबी ﷺ वर्षाका लागि यो दुआ गर्नुहुन्थ्यो।"),
        "dua_seeing_clouds" to DuaText("कालो बादल देख्दा", "हे अल्लाह! म यसको खराबीबाट तपाईंको शरण माग्छु।", "आकाशमा बादल देख्दा; वर्षा भए 'अल्लाहुम्मा सय्यिबन नाफिआ'।", "नबी ﷺ बादल देखेर काम छोड्नुहुन्थ्यो र यो दुआ गर्नुहुन्थ्यो।"),
        "dua_jamarat" to DuaText("जमरातमा ढुंगा हान्दा", "अल्लाह सबैभन्दा महान हुनुहुन्छ।", "हरेक ढुंगा हान्दा।", "नबी ﷺ हरेक ढुंगासँग तकबीर भन्नुहुन्थ्यो, अनि पहिलो र दोस्रो जमरापछि किब्लातर्फ फर्केर लामो दुआ गर्नुहुन्थ्यो।"),
        "dua_rabbi_ainni" to DuaText("हे मेरा रब, मलाई मद्दत गर्नुहोस्, मेरो विरुद्ध होइन", "हे मेरा रब! मलाई मद्दत गर्नुहोस् र मेरो विरुद्ध मद्दत नगर्नुहोस्, मलाई विजय दिनुहोस् र ममाथि विजय नदिनुहोस्, मेरो पक्षमा योजना गर्नुहोस् र मेरो विरुद्ध योजना नगर्नुहोस्, मलाई मार्गदर्शन दिनुहोस् र मार्गदर्शन मेरा लागि सजिलो पार्नुहोस्, र जसले ममाथि अन्याय गर्छ उसको विरुद्ध मलाई मद्दत गर्नुहोस्।", "नबी ﷺ को व्यापक दुआ (सुरुको भाग)।", "संसार र दीनका सबै मद्दत समेट्ने दुआ।"),
        "dua_ati_nafsi_taqwaha" to DuaText("मेरो मनलाई यसको तक्वा दिनुहोस्", "हे अल्लाह! मेरो मनलाई यसको तक्वा दिनुहोस् र यसलाई पवित्र पार्नुहोस्, तपाईं नै यसलाई सर्वोत्तम पवित्र पार्नुहुने हुनुहुन्छ, तपाईं नै यसका संरक्षक र मालिक हुनुहुन्छ।", "मनको सुधार र शुद्धिकरणका लागि।", "नबी ﷺ यो दुआ गर्नुहुन्थ्यो।"),
        "dua_iqsim_lana_khashyatik" to DuaText("हामीलाई तपाईंको यस्तो डर दिनुहोस्", "हे अल्लाह! हामीलाई तपाईंको यति डर दिनुहोस् जुन हाम्रो र तपाईंको अवज्ञाबीच बाधा बनोस्, यति आज्ञाकारिता जसले हामीलाई तपाईंको जन्नतसम्म पुर्याओस्, र यति विश्वास जसले संसारका संकट हाम्रा लागि सजिलो बनाओस्। जबसम्म हामीलाई जीवित राख्नुहुन्छ हाम्रा कान, आँखा र शक्तिबाट हामीलाई लाभ दिनुहोस् र तिनलाई हाम्रा उत्तराधिकारी बनाउनुहोस्। जसले हामीमाथि अन्याय गर्छ उसबाट हाम्रो बदला लिनुहोस्, शत्रुहरूविरुद्ध हामीलाई मद्दत गर्नुहोस्, हाम्रो संकट हाम्रो दीनमा नपार्नुहोस्, संसारलाई हाम्रो सबैभन्दा ठूलो चिन्ता र हाम्रो ज्ञानको सीमा नबनाउनुहोस्, र हामीमाथि त्यस्तो व्यक्ति नलाद्नुहोस् जसले हामीमाथि दया गर्दैन।", "सभाबाट उठ्दा — नबी ﷺ विरलै यो दुआ नगरी उठ्नुहुन्थ्यो।", "दीन, संसार र आखिरतको भलाइको व्यापक दुआ।"),
        "dua_infani_bima_allamtani" to DuaText("जे सिकाउनुभयो त्यसबाट लाभ दिनुहोस्", "हे अल्लाह! तपाईंले मलाई जे सिकाउनुभयो त्यसबाट मलाई लाभ दिनुहोस्, मलाई त्यो सिकाउनुहोस् जुन मलाई लाभदायक छ, र मेरो ज्ञान बढाइदिनुहोस्।", "ज्ञान प्राप्त गर्दा वा पढाइअघि।", "उपयोगी ज्ञान र त्यसमा अमलको दुआ।"),
        "dua_jar_su" to DuaText("नराम्रो छिमेकीबाट शरण", "हे अल्लाह! म स्थायी बासस्थानको नराम्रो छिमेकीबाट तपाईंको शरण माग्छु, किनकि यात्राको छिमेकी त बदलिन्छ।", "नराम्रो छिमेकीबाट सुरक्षाका लागि।", "नबी ﷺ ले यसबाट शरण माग्न आदेश दिनुभयो।"),
        "dua_ishfi_abdak" to DuaText("बिरामीको निको हुनका लागि", "हे अल्लाह! आफ्नो दासलाई निको पार्नुहोस् ताकि ऊ तपाईंका लागि शत्रुसँग लडोस् वा तपाईंका लागि नमाजतर्फ हिँडेर जाओस्।", "बिरामी भेट्दा उसका लागि।", "नबी ﷺ ले बिरामीका लागि यो भन्न सिकाउनुभयो।"),
        "dua_la_mania" to DuaText("तपाईंले दिएको कसैले रोक्न सक्दैन", "अल्लाहबाहेक कोही पूज्य छैन, उहाँ एक्लै हुनुहुन्छ, उहाँको कोही साझेदार छैन, राज्य र प्रशंसा उहाँकै हो र उहाँ हरेक कुरामा सर्वशक्तिमान हुनुहुन्छ। हे अल्लाह! तपाईंले जे दिनुहुन्छ त्यो कसैले रोक्न सक्दैन र तपाईंले जे रोक्नुहुन्छ त्यो कसैले दिन सक्दैन, र कुनै धनीको धन तपाईंको सामु काम लाग्दैन।", "फर्ज नमाजको सलामपछि।", "नबी ﷺ हरेक फर्ज नमाजपछि यो भन्नुहुन्थ्यो।"),
        "dua_slaughtering" to DuaText("पशु जिबह गर्दा", "अल्लाहको नाममा, र अल्लाह सबैभन्दा महान हुनुहुन्छ।", "कुर्बानी वा जिबह गर्दा।", "नबी ﷺ ले कुर्बानीको समयमा बिस्मिल्लाह र तकबीर भन्नुभयो।"),
        "dua_undressing" to DuaText("लुगा फुकाल्दा", "अल्लाहको नाममा।", "लुगा फुकाल्दा (नुहाउँदा वा लुगा फेर्दा)।", "जिन्नको नजर र मानिसको गुप्ताङ्गबीच पर्दा बन्छ।"),
        "dua_ilbas_jadidan" to DuaText("कसैलाई नयाँ लुगामा देख्दा", "नयाँ लगाऊ, प्रशंसनीय जीवन बिताऊ र शहीद भएर मर।", "कुनै मुस्लिम भाइलाई नयाँ लुगामा देखेर।", "नबी ﷺ ले उमर (र.) लाई नयाँ लुगामा देखेर यो दुआ दिनुभयो।"),
        "dua_hajj_la_riya" to DuaText("देखावटबाट मुक्त हज", "हे अल्लाह! यस्तो हज जसमा न देखावट होस् न प्रसिद्धिको चाहना।", "हजको नियतको समयमा निष्ठाका लागि।", "नबी ﷺ ले हजको समयमा यो दुआ गर्नुभयो।"),
        "dua_q_muslimayni_laka" to DuaText("हामीलाई आज्ञाकारी बनाउनुहोस् (इब्राहीम र इस्माईल अ.)", "हे हाम्रा रब! हामी दुवैलाई तपाईंको आज्ञाकारी बनाउनुहोस् र हाम्रा सन्तानबाट पनि एउटा समुदायलाई तपाईंको आज्ञाकारी बनाउनुहोस्, हामीलाई उपासनाका विधि देखाउनुहोस् र हाम्रो तौबा स्वीकार गर्नुहोस्, निश्चय नै तपाईं तौबा स्वीकार गर्नुहुने, दयालु हुनुहुन्छ।", "आफ्नो र सन्तानका लागि आज्ञाकारिताको दुआ।", "काबा निर्माणको समयको दुआ।"),
        "dua_q_iftah_baynana" to DuaText("हाम्रो बीच निर्णय गर्नुहोस् (शुऐब अ.)", "हे हाम्रा रब! हाम्रो र हाम्रो समुदायबीच सत्यले निर्णय गरिदिनुहोस्, र तपाईं सर्वोत्तम निर्णय गर्नुहुने हुनुहुन्छ।", "सत्य र असत्यबीच निर्णयका लागि।", "समुदायले अस्वीकार गर्दा शुऐब (अ.) को दुआ।"),
        "dua_q_la_akuna_zahiran" to DuaText("कहिल्यै अपराधीहरूको सहयोगी होइन (मूसा अ.)", "हे मेरा रब! तपाईंले ममाथि गर्नुभएको कृपाका कारण म कहिल्यै अपराधीहरूको सहयोगी बन्नेछैनँ।", "अल्लाहको कृपाको धन्यवाद र पापीहरूलाई सहयोग नगर्ने प्रतिज्ञा।", "तौबापछि मूसा (अ.) को प्रतिज्ञा।"),
        "dua_q_nuh_unsurni" to DuaText("मलाई मद्दत गर्नुहोस्, उनीहरूले मलाई झुटो भने (नूह अ.)", "हे मेरा रब! मलाई मद्दत गर्नुहोस् किनकि उनीहरूले मलाई झुटो ठहराए।", "जब मानिसहरू झुटो ठहराउँछन् र सत्य मान्दैनन्।", "नूह (अ.) को दुआ जुन स्वीकार भयो।"),
        "dua_q_ihkum_bil_haqq" to DuaText("हे मेरा रब, सत्यले निर्णय गर्नुहोस्", "हे मेरा रब! सत्यले निर्णय गर्नुहोस्। र हाम्रा रब परम दयालु हुनुहुन्छ, जसबाट तिमीहरूले रचेका कुराहरूविरुद्ध मद्दत मागिन्छ।", "झुटा कुरा र आरोपहरूको सामना गर्दा।", "नबी ﷺ लाई सिकाइएको दुआ।"),
        "dua_ghalabatid_dayn" to DuaText("भारी ऋण र शत्रुबाट शरण", "हे अल्लाह! म ऋणको दबाब, शत्रुको प्रभुत्व र शत्रुहरूको खुसीबाट तपाईंको शरण माग्छु।", "ऋणको भार र शत्रुको प्रभुत्वबाट सुरक्षा।", "नबी ﷺ यी कुराहरूबाट शरण माग्नुहुन्थ्यो।"),
        "dua_faqr_qillah_dhillah" to DuaText("गरिबी र अपमानबाट शरण", "हे अल्लाह! म गरिबी, अभाव र अपमानबाट तपाईंको शरण माग्छु, र अन्याय गर्नबाट वा ममाथि अन्याय हुनबाट।", "तंगी, अभाव र अपमानबाट बच्न।", "नबी ﷺ ले सिकाउनुभएको शरण।"),
        "dua_five_things_new_muslim" to DuaText("क्षमा, दया, मार्गदर्शन, सुरक्षा, जीविका", "हे अल्लाह! मलाई क्षमा गर्नुहोस्, ममाथि दया गर्नुहोस्, मलाई मार्गदर्शन दिनुहोस्, मलाई सुरक्षा दिनुहोस् र मलाई जीविका दिनुहोस्।", "नबी ﷺ नयाँ मुस्लिमलाई नमाजसँगै यो दुआ सिकाउनुहुन्थ्यो।", "नबी ﷺ ले भन्नुभयो: यी शब्दले तिम्रा लागि संसार र आखिरत समेट्छन्।"),
        "dua_ruku_laka_raka_tu" to DuaText("रुकूमा — तपाईंका लागि रुकू गरेँ", "हे अल्लाह! मैले तपाईंका लागि रुकू गरेँ, तपाईंमाथि ईमान ल्याएँ र तपाईंमा समर्पित भएँ। मेरा कान, आँखा, मस्तिष्क, हड्डी र नसाहरू तपाईंको सामु झुके।", "रुकूमा (विशेष गरी नफ्ल नमाजमा)।", "नबी ﷺ रुकूमा यो पढ्नुहुन्थ्यो।"),
        "dua_sujood_laka_sajadtu" to DuaText("सजदामा — तपाईंलाई सजदा गरेँ", "हे अल्लाह! मैले तपाईंलाई सजदा गरेँ, तपाईंमाथि ईमान ल्याएँ र तपाईंमा समर्पित भएँ। मेरो अनुहार उहाँको सामु सजदामा छ जसले यसलाई सृष्टि गर्नुभयो, आकार दिनुभयो र यसका कान र आँखा खोलिदिनुभयो। बरकतमय हुनुहुन्छ अल्लाह, सर्वोत्तम सृष्टिकर्ता।", "सजदामा (विशेष गरी नफ्ल नमाजमा)।", "नबी ﷺ सजदामा यो पढ्नुहुन्थ्यो।"),
        "dua_ruku_sujood_subhanaka" to DuaText("हे हाम्रा रब, तपाईं पवित्र हुनुहुन्छ — मलाई क्षमा गर्नुहोस्", "हे अल्लाह, हाम्रा रब! तपाईं पवित्र हुनुहुन्छ आफ्नो प्रशंसासहित। हे अल्लाह! मलाई क्षमा गर्नुहोस्।", "रुकू र सजदामा।", "आइशा (र.): नबी ﷺ रुकू र सजदामा धेरै यो पढ्नुहुन्थ्यो।"),
        "dua_q_musa_li_akhi" to DuaText("मलाई र मेरो भाइलाई क्षमा गर्नुहोस् (मूसा अ.)", "हे मेरा रब! मलाई र मेरो भाइलाई क्षमा गर्नुहोस् र हामीलाई आफ्नो कृपामा प्रवेश गराउनुहोस्, र तपाईं सबै दयालुहरूभन्दा बढी दयालु हुनुहुन्छ।", "आफ्नो र भाइ/प्रियजनका लागि क्षमा।", "हारून (अ.) का लागि मूसा (अ.) को दुआ।"),
        "dua_q_ufawwidu_amri" to DuaText("म आफ्नो काम अल्लाहको जिम्मामा सुम्पन्छु", "र म आफ्नो काम अल्लाहको जिम्मामा सुम्पन्छु, निश्चय नै अल्लाह दासहरूलाई राम्ररी देख्नुहुन्छ।", "जब मानिसहरू विरोध गर्छन् र मामिला अल्लाहको जिम्मामा सुम्पनुपर्छ।", "फिरऔनका मानिसहरूमध्येको मोमिनको वचन; त्यसपछि अल्लाहले उसलाई उनीहरूका षड्यन्त्रबाट बचाउनुभयो।"),
        "dua_q_hawariyyun" to DuaText("हवारीहरूको दुआ — हामीलाई साक्षीहरूमा लेख्नुहोस्", "हे हाम्रा रब! तपाईंले जे उतार्नुभयो त्यसमा हामीले ईमान ल्यायौँ र रसूलको अनुसरण गर्यौँ, त्यसैले हामीलाई साक्षी दिनेहरूमा लेख्नुहोस्।", "ईमान र रसूलको अनुसरणमा दृढताका लागि।", "ईसा (अ.) का हवारीहरूको दुआ।"),
        "dua_q_la_tukhzini" to DuaText("मलाई अपमानित नगर्नुहोस् (इब्राहीम अ.)", "र जुन दिन मानिसहरूलाई उठाइनेछ त्यस दिन मलाई अपमानित नगर्नुहोस्।", "कयामतको अपमानबाट बच्न।", "आखिरतका लागि इब्राहीम (अ.) को दुआ।"),
        "dua_iftar_laka_sumtu" to DuaText("इफ्तार — तपाईंका लागि रोजा बसेँ", "हे अल्लाह! मैले तपाईंका लागि रोजा बसेँ र तपाईंकै जीविकाले इफ्तार गरेँ।", "रोजा खोल्दा (इफ्तारको प्रसिद्ध दुआ)।", "नबी ﷺ इफ्तारको समयमा यो भन्नुहुन्थ्यो। यो मुरसल रिवायत हो जसलाई अन्य रिवायतले बल दिन्छन्; हनफी र अधिकांश विद्वानहरूमा इफ्तारमा यो पढ्ने चलन छ।"),
        "dua_iftar_ibn_umar" to DuaText("इफ्तार — तपाईंको विशाल कृपाले मलाई क्षमा गर्नुहोस्", "हे अल्लाह! म तपाईंको त्यो कृपाको आधारमा जसले हरेक कुरालाई घेरेको छ, तपाईंसँग याचना गर्छु कि मलाई क्षमा गर्नुहोस्।", "इफ्तारको समयमा — अब्दुल्लाह बिन अम्र (र.) यो दुआ गर्नुहुन्थ्यो; इफ्तारमा रोजेदारको दुआ अस्वीकार हुँदैन।", "हदीस: इफ्तारको समयमा रोजेदारको दुआ अस्वीकार गरिँदैन।"),
        "dua_inni_saim" to DuaText("रोजामा कसैले उक्साएमा", "म रोजामा छु, म रोजामा छु।", "रोजा भएको बेला कसैले गाली गरेमा वा झगडा गरेमा।", "नबी ﷺ ले भन्नुभयो: रोजा ढाल हो, त्यसैले रोजेदारले अश्लील कुरा वा मूर्खता नगरोस् — कसैले झगडा गरे दुई पटक यो भनोस्।"),
        "dua_eid_takbeer" to DuaText("ईदगाह जाँदा तकबीर", "अल्लाह सबैभन्दा महान हुनुहुन्छ, अल्लाह सबैभन्दा महान हुनुहुन्छ, अल्लाहबाहेक कोही पूज्य छैन, र अल्लाह सबैभन्दा महान हुनुहुन्छ, अल्लाह सबैभन्दा महान हुनुहुन्छ, र सम्पूर्ण प्रशंसा अल्लाहकै लागि हो।", "चाँद रातदेखि ईदुल फित्रको नमाजसम्म, विशेष गरी ईदगाह जाँदा।", "कुरआनको आदेश: 'ताकि तिमीहरू गन्ती पूरा गर र अल्लाहको महानता वर्णन गर' (अल-बकरा २:१८५)। इब्न मसऊद (र.) यही तकबीर भन्नुहुन्थ्यो।"),
        "dua_ahsin_aqibatana" to DuaText("हरेक काममा हाम्रो अन्त्य राम्रो पार्नुहोस्", "हे अल्लाह! सबै काममा हाम्रो अन्त्य राम्रो पार्नुहोस्, र हामीलाई संसारको अपमान र आखिरतको सजायबाट बचाउनुहोस्।", "हरेक कामको राम्रो परिणामका लागि।", "जसले यो दुआ गर्छ र परीक्षाअघि मर्छ, ऊ (फित्नाबाट सुरक्षित) मर्छ।"),
        "dua_fadlika_wa_rahmatik" to DuaText("तपाईंको अनुग्रह र कृपा माग्छु", "हे अल्लाह! म तपाईंसँग तपाईंको अनुग्रह र कृपा माग्छु, किनकि यिनको मालिक तपाईंबाहेक कोही छैन।", "जीविका र कृपा माग्दा।", "नबी ﷺ कहाँ पाहुना आए तर खाना थिएन, उहाँले यो दुआ गर्नुभयो, अनि उपहार आयो।"),
        "dua_allahu_akbar_kabira_2696" to DuaText("एक ग्रामीणलाई सिकाइएका शब्द", "अल्लाहबाहेक कोही पूज्य छैन, उहाँ एक्लै हुनुहुन्छ, उहाँको कोही साझेदार छैन। अल्लाह अत्यन्त महान हुनुहुन्छ, अल्लाहका लागि प्रशस्त प्रशंसा छ, सारा संसारका रब अल्लाह पवित्र हुनुहुन्छ, र प्रभुत्वशाली, बुद्धिमान अल्लाहबाहेक कुनै शक्ति र सामर्थ्य छैन।", "जिक्र र दुआको व्यापक वाक्य — एक ग्रामीणलाई सिकाइएको।", "त्यसपछि 'अल्लाहुम्मग्फिर ली वरहम्नी वहदिनी वरजुक्नी' भन्न सिकाउनुभयो।"),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("अघि र पछिका पाप क्षमा गर्नुहोस्", "हे अल्लाह! मेरा ती पाप क्षमा गर्नुहोस् जुन मैले पहिले गरेँ र पछि गरेँ, लुकेर गरेँ र खुला गरेँ, जुन अति गरेँ, र जुन तपाईं मभन्दा बढी जान्नुहुन्छ। तपाईं नै अगाडि बढाउनुहुने र तपाईं नै पछाडि पार्नुहुने हुनुहुन्छ, तपाईंबाहेक कोही पूज्य छैन।", "तशह्हुद र दुरूदपछि सलामअघि।", "नबी ﷺ नमाजको अन्त्यमा तशह्हुद र सलामबीच यो पढ्नुहुन्थ्यो।"),
        "dua_jiddi_wa_hazli" to DuaText("गम्भीरता र ठट्टाका पाप क्षमा गर्नुहोस्", "हे अल्लाह! मेरा ती पाप क्षमा गर्नुहोस् जुन गम्भीरतामा र ठट्टामा भए, गल्तीले र जानीजानी भए — र यी सबै ममा छन्।", "जानी-नजानी सबै प्रकारका पापको क्षमा।", "नबी ﷺ को व्यापक इस्तिगफार।"),
        "dua_rising_ruku_mil" to DuaText("रुकूपछि — आकाशभरि प्रशंसा", "हे हाम्रा रब! तपाईंकै लागि सम्पूर्ण प्रशंसा हो, आकाशभरि, पृथ्वीभरि, र त्यसपछि तपाईंले जे चाहनुहुन्छ त्यसभरि।", "रुकूबाट उठेर 'रब्बना लकल हम्द' सँगै।", "नबी ﷺ रुकूबाट उठेर यो भन्नुहुन्थ्यो।"),
        "dua_istiftah_kabira" to DuaText("अल्लाह महान, प्रशस्त प्रशंसा", "अल्लाह अत्यन्त महान हुनुहुन्छ, अल्लाहका लागि प्रशस्त प्रशंसा छ, र बिहान-साँझ अल्लाहको पवित्रता।", "नमाज सुरु गर्दा (सनाको एक रूप)।", "नबी ﷺ ले भन्नुभयो: यसका लागि आकाशका ढोका खोलिए।"),
        "dua_q_ashku_bathhi" to DuaText("म अल्लाहसँग मात्र गुनासो गर्छु (याकूब अ.)", "म आफ्नो दुःख र पीडाको गुनासो अल्लाहसँग मात्र गर्छु।", "गहिरो दुःख र वियोगको समयमा।", "याकूब (अ.) ले यूसुफ (अ.) को वियोगमा यो भन्नुभयो।"),
        "dua_q_khayrun_hafiza" to DuaText("अल्लाह सर्वोत्तम रक्षक हुनुहुन्छ", "अल्लाह नै सर्वोत्तम रक्षक हुनुहुन्छ, र उहाँ सबै दयालुहरूभन्दा बढी दयालु हुनुहुन्छ।", "छोराछोरी वा प्रियजनलाई यात्रामा पठाउँदा।", "याकूब (अ.) ले आफ्नो छोरालाई अल्लाहको जिम्मामा सुम्पँदा यो भन्नुभयो।"),
        "dua_q_aqraba_rashada" to DuaText("मेरा रबले मलाई भलाइको नजिकको बाटो देखाउनुहुनेछ", "आशा छ मेरा रबले मलाई योभन्दा पनि भलाइको नजिकको बाटो देखाउनुहुनेछ।", "कुनै काममा राम्रो बाटो खोज्दा।", "बिर्सिँदा यो भन्न नबी ﷺ लाई सिकाइयो।"),
        "dua_q_sawa_as_sabil" to DuaText("मलाई सिधा बाटो देखाउनुहोस् (मूसा अ.)", "आशा छ मेरा रबले मलाई सिधा बाटो देखाउनुहुनेछ।", "नयाँ यात्रा वा अपरिचित बाटोमा हिँड्दा।", "मदयनतर्फ लाग्दा मूसा (अ.) ले यो भन्नुभयो।"),
        "dua_q_not_among_wrongdoers" to DuaText("मलाई अत्याचारीहरूमा सामेल नगर्नुहोस्", "हे मेरा रब! मलाई अत्याचारी समुदायमा सामेल नगर्नुहोस्।", "अत्याचारीहरूबाट अलग राख्न अल्लाहसँग दुआ।"),
        "dua_q_do_not_make_us_trial" to DuaText("हामीलाई परीक्षा नबनाउनुहोस्", "हे हाम्रा रब! हामीलाई काफिरहरूका लागि परीक्षा नबनाउनुहोस् र हामीलाई क्षमा गर्नुहोस्, हे हाम्रा रब! निश्चय नै तपाईं प्रभुत्वशाली, बुद्धिमान हुनुहुन्छ।", "इब्राहीम (अ.) र उहाँका साथीहरूको दुआ।"),
        "dua_morning_witness" to DuaText("बिहान तौहीदको साक्षी", "हे अल्लाह! मैले बिहान गरेँ, म तपाईंलाई, तपाईंको अर्श बोक्नेहरूलाई, तपाईंका फरिश्ताहरूलाई र तपाईंको सम्पूर्ण सृष्टिलाई साक्षी राख्छु कि तपाईं नै अल्लाह हुनुहुन्छ, तपाईंबाहेक कोही पूज्य छैन, तपाईं एक्लै हुनुहुन्छ, तपाईंको कोही साझेदार छैन, र मुहम्मद ﷺ तपाईंका दास र रसूल हुनुहुन्छ।", "रिवायतमा बिहान चार पटक पढ्ने उल्लेख छ।"),
        "dua_evening_witness" to DuaText("साँझ तौहीदको साक्षी", "हे अल्लाह! मैले साँझ गरेँ, म तपाईंलाई, तपाईंको अर्श बोक्नेहरूलाई, तपाईंका फरिश्ताहरूलाई र तपाईंको सम्पूर्ण सृष्टिलाई साक्षी राख्छु कि तपाईं नै अल्लाह हुनुहुन्छ, तपाईंबाहेक कोही पूज्य छैन, तपाईं एक्लै हुनुहुन्छ, तपाईंको कोही साझेदार छैन, र मुहम्मद ﷺ तपाईंका दास र रसूल हुनुहुन्छ।", "रिवायतमा साँझ चार पटक पढ्ने उल्लेख छ।"),
        "dua_morning_blessing" to DuaText("बिहान कृपाहरूको धन्यवाद", "हे अल्लाह! बिहान मलाई वा तपाईंको कुनै सृष्टिलाई जे कृपा मिल्यो त्यो तपाईंबाट मात्र हो, तपाईंको कोही साझेदार छैन; त्यसैले सम्पूर्ण प्रशंसा र धन्यवाद तपाईंकै हो।", "बिहान अल्लाहका कृपाहरूका लागि धन्यवादको जिक्र।"),
        "dua_evening_blessing" to DuaText("साँझ कृपाहरूको धन्यवाद", "हे अल्लाह! साँझ मलाई वा तपाईंको कुनै सृष्टिलाई जे कृपा मिल्यो त्यो तपाईंबाट मात्र हो, तपाईंको कोही साझेदार छैन; त्यसैले सम्पूर्ण प्रशंसा र धन्यवाद तपाईंकै हो।", "साँझ अल्लाहका कृपाहरूका लागि धन्यवादको जिक्र।"),
    )
}
